import{_ as r,o as l,c as a,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const m=JSON.parse('{"title":"Den Halbjahreswechsel am Berufskolleg durchführen","description":"","frontmatter":{"title":"Den Halbjahreswechsel am Berufskolleg durchführen","source_pageid":1357,"source_revision":5056},"headers":[],"relativePath":"schild3/schueler/halbjahreswechsel-am-bk-tutorial.md","filePath":"schild3/schueler/halbjahreswechsel-am-bk-tutorial.md"}'),i={name:"schild3/schueler/halbjahreswechsel-am-bk-tutorial.md"};function u(h,s,o,c,d,g){return l(),a("div",null,[...s[0]||(s[0]=[t('<h1 id="den-halbjahreswechsel-am-berufskolleg-durchfuhren" tabindex="-1">Den Halbjahreswechsel am Berufskolleg durchführen <a class="header-anchor" href="#den-halbjahreswechsel-am-berufskolleg-durchfuhren" aria-label="Permalink to &quot;Den Halbjahreswechsel am Berufskolleg durchführen&quot;">​</a></h1><p>Schließen Sie endende Bildungsgänge und vorzeitige Prüfungen ab, bevor Sie die übrigen aktiven Schülerinnen und Schüler in das nächste Halbjahr übertragen.</p><h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>Der Halbjahreswechsel am BK funktioniert grundsätzlich analog zum einfachen Halbjahreswechsel an anderen Schulen. Am BK ist jedoch zu beachten, dass die 3,5-jährigen Bildungsgänge zum Halbjahr enden und damit bei ihnen <em>Abschlüsse</em> und <em>Abgänge</em> anliegen.</p><p>Weiterhin sind eventuelle vorzeitige Prüflinge in den <em>Abschluss</em> zu übertragen.</p><p>Alle übrigen Schüler mit dem <strong>Status</strong> <em>Aktiv</em> sind ins neue Halbjahr zu übertragen. Eine Ausnahme bilden hier gegebenenfalls schon versetzte Schüler.</p><h2 id="berufsschulabsolventen-ausschulen" tabindex="-1">Berufsschulabsolventen ausschulen <a class="header-anchor" href="#berufsschulabsolventen-ausschulen" aria-label="Permalink to &quot;Berufsschulabsolventen ausschulen&quot;">​</a></h2><p>Während der Vorbereitung der Zeugnisse sollten alle Absolventen je nach Leistungsstand die <strong>Zeugnisart</strong> <em>Abschlusszeugnis</em> oder <em>Abgangszeugnis</em> erhalten haben.</p><p>Der <strong>Entlassjahrgang</strong> und die <strong>Art des Abschlusses</strong> sollten ebenfalls schon eingetragen sein.</p><h3 id="auf-korrekturen-prufen" tabindex="-1">Auf Korrekturen prüfen <a class="header-anchor" href="#auf-korrekturen-prufen" aria-label="Permalink to &quot;Auf Korrekturen prüfen&quot;">​</a></h3><ul><li>Kontrollieren Sie den <strong>Entlassjahrgang&#39;</strong> und die <strong>Art des Abschluss</strong>.</li><li>Kontrollieren Sie die Daten <strong>Konferenzdatum</strong>, <strong>Zeugnisdatum</strong> und <strong>Entlassdatum</strong>.</li><li>Prüfen Sie auf die üblichen Korrekturen. Unter <em>Schüler ➜ Akt. Halbjahr ➜ Leistungsdaten</em> ➜ <strong>Zeugnis/Abschluss</strong> müssen die Daten korrekt eingetragen sein. Nutzen Sie gegebenenfalls den Schülerfilter, grundsätzlich sollten aber alle Schüler manuell geprüft werden.</li></ul><p>Achten Sie hierbei darauf, dass die Felder <em>Vers-Vermerk</em>, <em>Abschluss-Art</em>, <em>Folgeklasse</em> (ist bei Abschlüssen und Abgängen leer) und <em>Zeugnisart</em> zusammen passen.</p><p>Dies bedeutet, dass wenn jemand abgeht, ist bei <strong>Abschluss-Art</strong> <em>Ohne Abschluss</em> und bei der <strong>Zeugnisart</strong> das <em>Abgangszeugnis</em> zu setzen.</p><h3 id="schuler-ausschulen" tabindex="-1">Schüler ausschulen <a class="header-anchor" href="#schuler-ausschulen" aria-label="Permalink to &quot;Schüler ausschulen&quot;">​</a></h3><p>Filtern Sie die Schüler, die gemeinsam über ein Zeugnisformular gedruckt werden, also zum Beispiel die mit gleichem Abschluss oder die Schüler, die Abgangszeugnisse bekommen.</p><p>Nutzen Sie hierzu <em>Gruppenprozesse ➜ Noten/Zeugnisvorbereitung</em> ➜ <strong>Zeugnisse drucken und Schüler ausschulen</strong>.</p>',16),e("div",{"data-hint-kind":"right",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"right","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"m8 12 3 3 5-6"})]),n("Richtig – Fertig")]),e("p",null,[n("Führen Sie im Anschluss den Halbjahreswechsel über "),e("em",null,"Verwaltung"),n(" ➜ "),e("code",null,"Halbjahreswechsel"),n(" durch.")])],-1),e("p",null,"Hierzu lassen sich die allgemeinen Tutorials hinzuziehen.",-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Halbjahreswechsel_am_BK_(Tutorial)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5056.")],-1)])])}const f=r(i,[["render",u]]);export{m as __pageData,f as default};
